import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: '2026-01-01T00:00:00.000Z'}],
  };
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => ({result: 'found it'})
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}};

describe('Turn Usage Reporting', () => {
  it('reports usage covering every provider call in a multi-round turn', async () => {
    let seenUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        seenUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [
          TOOL_CALL,
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 15, outputTokens: 5, totalTokens: 20}},
        ],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}}],
      ]),
      promptBuilder,
      registryReturning(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seenUsage).toEqual({
      inputTokens: 45,
      outputTokens: 17,
      totalTokens: 62,
    });
  });

  it('accumulates usage safely when some rounds report no usage', async () => {
    let seenUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        seenUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}], // No usage this round
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 5, totalTokens: 10}}],
      ]),
      promptBuilder,
      registryReturning(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seenUsage).toEqual({
      inputTokens: 15,
      outputTokens: 7,
      totalTokens: 22,
    });
  });
});
EOF

cat << 'EOF' > patch.js
const fs = require('fs');
const file = 'specs/hal-engine-config-hooks/spec.md';
let content = fs.readFileSync(file, 'utf8');

const oldText = "- `afterModelResponse` is called once per user message after the round loop exits ([chatOrchestrator.ts#L148](../../src/orchestration/chatOrchestrator.ts#L148)), and is passed the `lastUsage` local — the most recent round's usage, not a sum across tool rounds, so a deployer using the hook for billing or audit under-counts every turn that ran tools.";
const newText = "- `afterModelResponse` is called once per user message after the round loop exits, and is passed the accumulated sum of usage across all rounds, so a deployer using the hook for billing or audit counts every provider call in that turn ([validated by: reports usage covering every provider call in a multi-round turn](../../src/orchestration/turn-usage.acceptance.test.ts#L42)). A provider that reports no usage on some rounds does not make the total undefined or NaN: the rounds that reported are still counted ([validated by: accumulates usage safely when some rounds report no usage](../../src/orchestration/turn-usage.acceptance.test.ts#L71)).";

if (content.includes(oldText)) {
  content = content.replace(oldText, newText);
  fs.writeFileSync(file, content);
  console.log("Patched successfully");
} else {
  console.log("Could not find old text");
}
EOF
node patch.js
